def convert_cached(dataset, kind, csv_path, out_path, seed, expected_n):
    """Conversion with a provenance sidecar so a cached conversion can be safely reused."""
    meta_path = out_path + ".meta.json"
    try:
        st = os.stat(csv_path)
        want = {"dataset": dataset, "kind": kind, "seed": seed, "norm_version": NORM_VERSION,
                "csv": os.path.abspath(csv_path), "csv_size": st.st_size,
                "csv_mtime": int(st.st_mtime), "expected_n": expected_n}
        if os.path.isfile(out_path) and os.path.isfile(meta_path):
            with open(meta_path, encoding="utf-8") as f:
                have = json.load(f)
            if have == want:
                n = sum(1 for ln in open(out_path, encoding="utf-8") if ln.strip())
                if n == expected_n:
                    log("reusing cached conversion %s (%d lines)" % (out_path, n))
                    return n
    except OSError:
        want = None
    n = convert(csv_path, out_path, seed, shuffle=True)
    if want is not None:
        with open(meta_path, "w", encoding="utf-8") as f:
            json.dump(want, f, indent=1)
    return n

